const page = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"A little room to read. Turn web articles into a quiet, beautifully typeset reading experience.\"><title>Folio — A little room to read</title><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='9' fill='%23394336'/%3E%3Ctext x='11' y='30' fill='%23f5f3ec' font-size='32' font-family='Georgia'%3Ef%3C/text%3E%3C/svg%3E\"><style>\n@font-face{font-family:\"Martina Plantijn\";src:url(\"/fonts/MartinaPlantijn-Regular.otf\") format(\"opentype\");font-weight:400;font-style:normal;font-display:swap;}\n@font-face{font-family:\"Martina Plantijn\";src:url(\"/fonts/MartinaPlantijn-Italic.otf\") format(\"opentype\");font-weight:400;font-style:italic;font-display:swap;}\n@font-face{font-family:\"Martina Plantijn\";src:url(\"/fonts/MartinaPlantijn-Bold.otf\") format(\"opentype\");font-weight:700;font-style:normal;font-display:swap;}\n@font-face{font-family:\"Martina Plantijn\";src:url(\"/fonts/MartinaPlantijn-BoldItalic.otf\") format(\"opentype\");font-weight:700;font-style:italic;font-display:swap;}\n:root{--font-serif:'Martina Plantijn','MartinaPlantijn',Georgia,'Times New Roman',serif;--paper:#f6f5f0;--ink:#292b26;--muted:#7e8077;--line:#dedfd5;--green:#404d3a;--panel:#eeeee6;--article-size:21px;--article-width:660px}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;line-height:1.5}button,input,textarea{font:inherit}button,a,input,textarea{outline-offset:5px}button,a{ -webkit-tap-highlight-color:transparent}button{cursor:pointer;color:inherit}button{border:0;background:none}a{color:inherit;text-underline-offset:4px}button:disabled{cursor:wait;opacity:.6}svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;vertical-align:middle}.serif,h1,h2,h3{font-family:var(--font-serif);font-weight:400}header{height:96px;margin:0 5.3%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font-family:var(--font-serif);font-size:34px;letter-spacing:-1.5px;padding:0}.brand svg{width:28px;height:30px;stroke-width:1.1}.nav{display:flex;align-items:center;gap:32px}.nav button{font-size:12px;color:var(--muted);padding:12px 0}.nav button.active{color:var(--ink)}.nav .about{border:1px solid var(--line);border-radius:50%;width:28px;height:28px;padding:0;font-family:var(--font-serif);font-size:15px}main.home{max-width:1200px;margin:auto;padding:0 46px}.intro{text-align:center;padding:76px 0 59px}.eyebrow{text-transform:uppercase;letter-spacing:2.2px;font-size:10px;font-weight:500;color:var(--muted);display:flex;gap:10px;align-items:center;justify-content:center}.dot{height:5px;width:5px;border-radius:50%;background:#738267}.intro h1{font-size:clamp(48px,5.4vw,76px);letter-spacing:-3.3px;line-height:1.12;margin:20px 0}.intro h1 em{font-weight:400;color:#75816c}.intro>p{font-size:14px;line-height:1.85;color:var(--muted);margin:0}.url-form{display:flex;align-items:center;gap:16px;border:1px solid #d5d8cc;background:#fcfcf8;box-shadow:0 4px 15px #3c453405;padding:7px 7px 7px 20px;border-radius:5px;max-width:640px;margin:29px auto 0;text-align:left}.url-form>svg{color:var(--muted);flex:none}.url-form input{min-width:0;flex:1;background:none;border:0;padding:11px 0;font-size:12px;color:var(--ink);outline:none}.primary{display:flex;justify-content:center;align-items:center;gap:17px;background:var(--green);color:#fff;border-radius:3px;padding:13px 21px;font-size:12px;white-space:nowrap}.primary svg{width:15px}.under-form{margin-top:14px!important;font-size:10px!important;letter-spacing:.2px}.under-form button{text-decoration:underline;text-underline-offset:3px;color:var(--muted);font-size:10px;padding:0}.error{max-width:640px;margin:12px auto 0;color:#9c4f3d;font-size:12px}.collection{padding:6px 0 50px}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.section-heading h2{font:17px var(--font-serif);margin:0}.section-heading h2 span{font:10px -apple-system,sans-serif;color:var(--muted);margin-left:12px}.section-heading>span{font-size:10px;letter-spacing:.3px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.card{border-top:1px solid var(--line);padding-top:15px}.card-open{padding:0;text-align:left;width:100%;display:block}.art{height:195px;position:relative;overflow:hidden;background:#dadbd0;border-radius:2px;transition:filter .25s}.card-open:hover .art{filter:brightness(1.05)}.art svg{height:100%;width:100%;stroke:none;display:block}.art .art-tag{position:absolute;bottom:13px;left:14px;background:#f8f7efed;border-radius:2px;padding:4px 7px;text-transform:uppercase;font-size:8px;letter-spacing:1.2px;color:#555d4c}.card-meta{display:flex;gap:9px;align-items:center;text-transform:uppercase;letter-spacing:1px;font-size:8px;color:var(--muted);margin:19px 0 9px}.card-meta i{width:2px;height:2px;background:var(--muted);border-radius:50%}.card h3{font-size:25px;line-height:1.2;letter-spacing:-.6px;margin:0 0 11px}.card p{font-size:11px;line-height:1.8;color:var(--muted);margin:0;max-width:94%}.card-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:17px;font-size:9px;color:var(--muted)}.card-bottom button{padding:3px 0 3px 10px}.card-bottom svg{height:15px;width:15px}.saved{fill:currentColor}.manifesto{margin-top:3px;display:flex;gap:20px;align-items:center;border-top:1px solid var(--line);padding:25px 0 32px}.manifesto>svg{width:25px;height:25px;flex:none;color:#86917d}.manifesto p{font:17px var(--font-serif);color:#747b6a;margin:0}.manifesto small{font:9px -apple-system,sans-serif;color:var(--muted);margin-left:auto;letter-spacing:.4px}footer{border-top:1px solid var(--line);padding:21px 5.3%;display:flex;justify-content:space-between;color:var(--muted);font-size:9px}.reader-top{display:flex;align-items:center;justify-content:space-between;padding:24px 5.3%;position:sticky;top:0;background:var(--paper);z-index:3;border-bottom:1px solid var(--line);gap:15px}.reader-actions{display:flex;gap:12px;align-items:center}.reader-actions button,.back{font-size:11px;display:flex;align-items:center;gap:8px}.reader-actions button{border:1px solid var(--line);border-radius:3px;padding:7px 10px}.progress{height:2px;position:fixed;top:0;left:0;background:#8b9b7d;z-index:8;width:0}.article{max-width:var(--article-width);margin:65px auto 100px;padding:0 24px}.article .eyebrow{justify-content:start}.article h1{font-size:clamp(38px,4.5vw,58px);line-height:1.12;letter-spacing:-1.8px;margin:22px 0}.article .dek{font:22px/1.5 var(--font-serif);color:var(--muted);margin:0 0 24px}.byline{display:flex;gap:12px;align-items:center;font-size:10px;color:var(--muted);padding-bottom:28px;margin-bottom:30px;border-bottom:1px solid var(--line)}.article-body{font:var(--article-size)/1.85 var(--font-serif);overflow-wrap:anywhere}.article-body h2{font-size:1.5em;line-height:1.3;margin:1.7em 0 .7em;letter-spacing:-.6px}.article-body h3{font-size:1.2em;line-height:1.4}.article-body p{margin:0 0 1.25em}.article-body blockquote{border-left:2px solid #8a977c;margin:1.6em 0;padding:0 0 0 25px;font-style:italic;color:var(--muted)}.article-body img{max-width:100%;height:auto}.article-body pre{white-space:pre-wrap;font-size:.75em}.article-body a{color:#788b65}.article-end{margin-top:42px;padding-top:24px;border-top:1px solid var(--line);font-size:11px;color:var(--muted);display:flex;justify-content:space-between;gap:20px}.settings{position:absolute;right:5%;top:70px;background:var(--paper);border:1px solid var(--line);padding:24px;border-radius:5px;width:260px;box-shadow:0 12px 40px #0001}.settings label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin-bottom:10px}.setting-row{display:flex;gap:8px;margin-bottom:20px}.setting-row:last-child{margin-bottom:0}.setting-row button{flex:1;justify-content:center}.setting-row button.chosen{border-color:var(--green);background:var(--panel)}dialog{width:min(540px,90vw);background:var(--paper);color:var(--ink);border:1px solid var(--line);padding:32px;border-radius:6px;box-shadow:0 20px 90px #0002}dialog::backdrop{background:#252d2655;backdrop-filter:blur(4px)}dialog h2{font-size:31px;margin:0 0 12px;letter-spacing:-1px}dialog p{font-size:12px;line-height:1.9;color:var(--muted)}.dialog-close{float:right;font-size:22px;line-height:1;padding:0 0 10px 15px}dialog input,dialog textarea{display:block;width:100%;border:1px solid var(--line);background:transparent;color:var(--ink);padding:12px;margin:12px 0;border-radius:3px}dialog textarea{height:220px;resize:vertical;font-size:12px;line-height:1.7}dialog label{font-size:10px;color:var(--muted)}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--green);color:white;border-radius:4px;padding:11px 20px;font-size:12px;z-index:10}.empty{padding:60px 0;text-align:center;color:var(--muted)}.empty h3{font-size:30px;margin:0 0 12px}[hidden]{display:none!important}body[data-theme=\"dark\"]{--paper:#20251f;--ink:#e3e5db;--muted:#a0aa96;--line:#3b4437;--green:#637957;--panel:#2c3528}body[data-theme=\"white\"]{--paper:#fff;--ink:#242424;--muted:#777;--line:#e6e6e6;--panel:#f3f3f3}body[data-font=\"sans\"] .article-body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}body[data-theme=\"dark\"] .url-form{background:#2c3528;border-color:#44503e}.focus header,.focus .reader-top{display:none}.focus .article{margin-top:70px}.focus-exit{position:fixed;bottom:24px;right:24px;border:1px solid var(--line);background:var(--paper);border-radius:25px;padding:11px 18px;font-size:11px;z-index:5}@media(min-width:1450px){.intro{padding-top:100px}.art{height:225px}}@media(max-width:700px){header{height:78px}.brand{font-size:29px}.nav{gap:20px}main.home{padding:0 23px}.intro{padding:56px 0 44px}.intro h1{letter-spacing:-2px;font-size:49px}.intro>p{font-size:12px}.url-form{gap:10px;padding-left:12px}.url-form input{font-size:11px}.primary{padding:13px;gap:9px}.primary span{display:none}.cards{grid-template-columns:1fr;gap:32px}.art{height:220px}.card h3{font-size:29px}.card p{font-size:13px}.card-meta{font-size:9px}.card-bottom{font-size:10px}.section-heading>span{display:none}.manifesto{margin-top:10px}.manifesto p{font-size:15px}.manifesto small{display:none}.reader-top{padding:18px 5%}.reader-actions{gap:6px}.reader-actions button{padding:7px}.reader-actions .action-label{display:none}.article{margin-top:40px}.article h1{font-size:42px}.article .dek{font-size:20px}footer{font-size:8px}.article-body{font-size:calc(var(--article-size) - 2px)}}\n</style></head><body><div class=\"progress\" id=\"progress\"></div><header><button class=\"brand\" id=\"brand\" aria-label=\"Folio home\"><svg viewBox=\"0 0 30 30\"><path d=\"M5 4h17v22H5zM9 8h9M9 12h7M9 16h8M9 20h4M22 7h3v22H8v-3\"/></svg>folio<span style=\"color:#8b967f\">.</span></button><nav class=\"nav\"><button id=\"nav-discover\" class=\"active\">Discover</button><button id=\"nav-saved\">My collection <span id=\"save-count\"></span></button><button class=\"about\" id=\"about-open\" aria-label=\"About Folio\">i</button></nav></header>\n<main class=\"home\" id=\"home\"><section class=\"intro\"><div class=\"eyebrow\"><span class=\"dot\"></span>A quieter corner of the internet</div><h1>A little room <em>to read.</em></h1><p>Good stories deserve your full attention.<br>Turn any article into a calm, beautiful reading experience.</p><form class=\"url-form\" id=\"url-form\"><svg viewBox=\"0 0 24 24\"><path d=\"m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 12a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1\" transform=\"translate(1 0) scale(.9)\"/></svg><input id=\"url-input\" aria-label=\"Article URL\" type=\"url\" placeholder=\"Paste an article link here…\" required><button class=\"primary\" id=\"read-button\" type=\"submit\">Start reading <span>↗</span></button></form><p class=\"under-form\">Just the words, without the noise. <span style=\"padding:0 5px\">·</span> Or <button id=\"paste-open\">paste article text</button></p><div class=\"error\" id=\"error\" role=\"alert\" hidden></div></section><section class=\"collection\"><div class=\"section-heading\"><h2 id=\"section-title\">A few things worth reading <span>THE FOLIO EDIT</span></h2><span id=\"section-note\">A small selection. A slower pace.</span></div><div class=\"cards\" id=\"cards\"></div><div class=\"empty\" id=\"empty\" hidden><h3>Your next good read belongs here.</h3><p>Open an article and tap the bookmark to add it to your collection.</p></div></section><div class=\"manifesto\"><svg viewBox=\"0 0 30 30\"><path d=\"M15 24V9m0 9C5 19 4 11 4 5c8 0 12 4 11 13Zm0 3c0-10 4-14 12-14 0 9-4 14-12 14Z\"/></svg><p>Less scrolling. More getting lost in a good story.</p><small>MADE FOR THE JOY OF READING</small></div></main>\n<section id=\"reader\" hidden><div class=\"reader-top\"><button class=\"back\" id=\"back\">← <span>Back to your corner</span></button><div class=\"reader-actions\"><button id=\"bookmark\" aria-label=\"Save article\"></button><button id=\"settings-toggle\" aria-expanded=\"false\" aria-controls=\"settings\"><span style=\"font-family:var(--font-serif);font-size:17px\">Aa</span><span class=\"action-label\">Appearance</span></button><button id=\"focus\"><svg viewBox=\"0 0 24 24\"><path d=\"M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5\"/></svg><span class=\"action-label\">Focus</span></button><div class=\"settings\" id=\"settings\" hidden><label>Text size</label><div class=\"setting-row\"><button id=\"size-down\" aria-label=\"Decrease text size\">A−</button><button id=\"size-up\" aria-label=\"Increase text size\">A+</button></div><label>Typeface</label><div class=\"setting-row\"><button data-font=\"serif\">Serif</button><button data-font=\"sans\">Sans</button></div><label>Page colour</label><div class=\"setting-row\"><button data-theme=\"paper\">Paper</button><button data-theme=\"white\">White</button><button data-theme=\"dark\">Night</button></div><label>Reading width</label><div class=\"setting-row\"><button data-width=\"660\">Narrow</button><button data-width=\"820\">Wide</button></div></div></div></div><article class=\"article\"><div class=\"eyebrow\" id=\"article-source\"></div><h1 id=\"article-title\"></h1><p class=\"dek\" id=\"article-dek\"></p><div class=\"byline\" id=\"article-byline\"></div><div class=\"article-body\" id=\"article-body\"></div><div class=\"article-end\"><span>A moment well spent.</span><a id=\"original\" target=\"_blank\" rel=\"noopener noreferrer\">Read at the source ↗</a></div></article></section><button id=\"focus-exit\" class=\"focus-exit\" hidden>↙ Leave focus view</button><footer><span>Folio · A place for good words.</span><span>No feeds. No noise. Just reading.</span></footer>\n<dialog id=\"paste-dialog\"><button class=\"dialog-close\" data-close aria-label=\"Close\">×</button><h2>Bring your own words.</h2><p>Copy the text from an article you can access, then give it a little room to breathe.</p><form id=\"paste-form\"><label for=\"paste-title\">ARTICLE TITLE</label><input id=\"paste-title\" placeholder=\"A story worth your time\" required maxlength=\"300\"><label for=\"paste-text\">ARTICLE TEXT</label><textarea id=\"paste-text\" placeholder=\"Paste the article here…\" required minlength=\"50\" maxlength=\"300000\"></textarea><button class=\"primary\" type=\"submit\">Open reading view ↗</button></form></dialog><dialog id=\"about-dialog\"><button class=\"dialog-close\" data-close aria-label=\"Close\">×</button><div class=\"eyebrow\" style=\"justify-content:start;margin-bottom:20px\">THE IDEA BEHIND FOLIO</div><h2>The internet, at a slower pace.</h2><p>Folio gives good writing a little breathing room. Paste a link, settle into a clean reading view, and make the page feel like your own.</p><p>Article extraction works best on publicly accessible, text-based pages. Paywalls, sign-in screens, bot protection and pages that load their text with JavaScript may prevent extraction. Folio does not bypass these restrictions.</p><p>Your collection and reading preferences stay in this browser. Saved articles don’t sync across devices, and clearing browser data removes them. Opening a link fetches that page through Folio’s server; page images load from their original websites. The sample essays are original Folio demonstrations.</p></dialog><div class=\"toast\" id=\"toast\" role=\"status\" hidden></div>\n<script>\nconst $=s=>document.querySelector(s);const bookmarkIcon='<svg viewBox=\"0 0 24 24\"><path d=\"M6 3h12v18l-6-4-6 4z\"/></svg>';\nconst art1='<svg viewBox=\"0 0 600 350\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"wall\" x2=\"1\" y2=\"1\"><stop stop-color=\"#cbc6b5\"/><stop offset=\"1\" stop-color=\"#e7e1cd\"/></linearGradient><linearGradient id=\"shade\"><stop stop-color=\"#6b705f\"/><stop offset=\"1\" stop-color=\"#3d493b\"/></linearGradient></defs><path fill=\"url(#wall)\" d=\"M0 0h600v350H0z\"/><path fill=\"#b5b5a0\" d=\"m0 350 245-135h355v135\"/><path fill=\"#c9c6b3\" d=\"M0 0h192v270L0 350\"/><path fill=\"#4d5949\" d=\"M212 25h212v236H212z\"/><path fill=\"#aab5a0\" d=\"M226 40h184v207H226z\"/><path fill=\"#697b5d\" d=\"M226 162c45-95 77-38 100-73 35-52 63 24 84-5v163H226\"/><path stroke=\"#d8d4c0\" stroke-width=\"8\" d=\"M317 40v207M226 165h184\"/><path fill=\"#ddd6c1\" d=\"m200 262 246-7 40 20-258 10z\"/><path fill=\"#8a8170\" d=\"m252 281 207-6 58 75H205z\"/><path fill=\"#515b46\" d=\"M79 245c-34-21-40-59-23-92 27 14 40 56 23 92m4-1c34-11 46-42 39-66-31 6-43 37-39 66\"/><path fill=\"#938975\" d=\"M62 242h43l-6 49H68z\"/></svg>';\nconst art2='<svg viewBox=\"0 0 600 350\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"sky\" x2=\"0\" y2=\"1\"><stop stop-color=\"#d5d8d0\"/><stop offset=\"1\" stop-color=\"#f1ead9\"/></linearGradient></defs><path fill=\"url(#sky)\" d=\"M0 0h600v350H0z\"/><path fill=\"#a3ac93\" d=\"M0 163q110-60 230 9t370-30v208H0z\"/><path fill=\"#78876b\" d=\"M0 220q120-92 260-6t340-11v147H0z\"/><path fill=\"#586b50\" d=\"M0 240q190-10 320 42t280-41v109H0z\"/><path fill=\"#364a3b\" d=\"M0 293q155-57 296 3t304-13v67H0z\"/><path fill=\"#bdbaa0\" d=\"M284 350c-89-56-37-70-45-91-6-15-34-11-25-28 17 13 69 6 60 33-12 37-11 28 65 86\"/><path fill=\"#475a43\" d=\"M430 149h10v142h-10zM433 106l-50 118h103zM507 132h7v135h-7zM510 91l-46 112h90z\"/><path fill=\"#64765a\" d=\"m89 142-41 91h79z\"/></svg>';\nconst art3='<svg viewBox=\"0 0 600 350\" xmlns=\"http://www.w3.org/2000/svg\"><defs><linearGradient id=\"desk\" x2=\"1\" y2=\"1\"><stop stop-color=\"#c3ac8e\"/><stop offset=\"1\" stop-color=\"#dfd1b9\"/></linearGradient></defs><path fill=\"url(#desk)\" d=\"M0 0h600v350H0z\"/><path fill=\"#b09a7a\" opacity=\".45\" d=\"m0 200 380-200h220L0 317z\"/><path fill=\"#ede7d7\" d=\"m185 85 199 17-17 210-201-17z\"/><path fill=\"#f6f0e2\" d=\"m185 85 19-2 197 18-18 211-16 0 17-210z\"/><path stroke=\"#bdb5a3\" stroke-width=\"2\" d=\"m221 144 118 10m-119 7 112 10m-113 8 118 10m-119 8 89 7m-90 14 118 10m-119 8 100 8m-101 9 115 9\"/><ellipse fill=\"#a58e70\" cx=\"452\" cy=\"240\" rx=\"65\" ry=\"17\"/><ellipse fill=\"#eee8d8\" cx=\"444\" cy=\"217\" rx=\"52\" ry=\"39\"/><path fill=\"#f1ecdd\" d=\"M394 179h99v34q-5 43-49 43t-50-43z\"/><ellipse fill=\"#e4dcc7\" cx=\"443\" cy=\"179\" rx=\"49\" ry=\"18\"/><ellipse fill=\"#574d37\" cx=\"443\" cy=\"180\" rx=\"40\" ry=\"12\"/><path stroke=\"#eee8d8\" stroke-width=\"13\" fill=\"none\" d=\"M492 187c49-8 43 47 0 41\"/><path stroke=\"#5a5d49\" stroke-width=\"7\" d=\"m130 113-24 175\"/><path stroke=\"#bca982\" stroke-width=\"4\" d=\"m127 127-21 161\"/></svg>';\nconst samples=[{id:'folio-spaces',title:'The quiet beauty of spaces that let us breathe',excerpt:'On natural light, well-worn materials, and the art of making a home feel like yourself.',category:'Architecture & living',art:art1,minutes:4,body:[['p','There is a particular kind of room that asks very little of you. It might have a chair near a window, a table marked by years of use, and a patch of afternoon light that moves, almost imperceptibly, across the floor. Nothing announces itself. And yet you find yourself wanting to stay.'],['p','We often talk about the things we put into our homes. We talk less about the space we leave between them. That space is where a room begins to breathe: where a familiar object can be noticed again, where daylight has something to fall on, where a person can simply sit.'],['h2','A room shaped by living'],['p','The most inviting homes rarely look finished. A book lies open on an armrest. A wooden surface has grown darker where hands meet it. A linen curtain hangs a little unevenly. These details are not failures of design; they are the record of a life taking place.'],['blockquote','A good room leaves enough space for you to become part of it.'],['p','Rather than beginning with a shopping list, perhaps we could begin by paying attention. Where do we sit in the morning? Which corner catches the last light? Which objects do we reach for without thinking? The answers describe a home more honestly than a floor plan.'],['h2','Letting materials grow older'],['p','Stone, wood, linen and clay all make their own agreements with time. They soften, develop colour, carry small imperfections. Choosing them means accepting change as part of the pleasure of a room.'],['p','A home need not be spare to feel calm. It needs a rhythm that suits the people who live in it. Sometimes finding that rhythm means moving a chair towards the window, leaving a wall empty, or putting the objects you love within reach.'],['p','Then, for a moment, stop arranging. Let the afternoon arrive.']]},{id:'folio-walking',title:'In praise of taking the long way home',excerpt:'A gentle reminder that the most interesting route is rarely the most efficient one.',category:'Culture & everyday life',art:art2,minutes:3,body:[['p','The shortest way home takes seventeen minutes. There is another way, along the water and through a street lined with trees, that takes nearly twice as long. For years I treated the difference as time lost. Lately, I have begun to think of it as time returned.'],['p','Walking without a precise ambition changes the way a place reveals itself. You notice a window you have passed a hundred times, the smell of bread from an open doorway, the small weekly changes in a garden. The familiar becomes a little unfamiliar again.'],['h2','A different measure of distance'],['p','Much of a working day is organised around getting somewhere: the next meeting, the end of a list, the answer to a question. A walk can be a rare stretch of time that has no such demand. Its value does not depend on what you produce at the other end.'],['blockquote','Some journeys are worth making a little longer.'],['p','There is no need to turn this into a practice to perfect. Leave your phone in your pocket. Take a turn you usually pass. If it rains, find a doorway and wait for a minute. The world has plenty to offer when you give it a little room.'],['h2','Coming back to yourself'],['p','By the time I reach my own street, the unresolved questions of the day have usually become quieter. They have not all been answered. But they have found their proper size.'],['p','I still take the short route sometimes. There are groceries to carry, people to meet, and evenings when getting home is the whole point. But when I can, I choose the extra distance. It has become one of the simplest things I do for myself.']]},{id:'folio-attention',title:'The simple pleasure of doing one thing',excerpt:'A cup of coffee. An open book. A small argument for being here, now.',category:'Mindful moments',art:art3,minutes:3,body:[['p','This morning I made coffee and sat by the window. A book was on the table. My phone was in another room. For the first few minutes, I kept expecting something to happen. Then I realised that something already was.'],['p','Attention is a curious thing. We talk about spending it, paying it, losing it. We rarely talk about enjoying it. Yet there is a distinct pleasure in giving yourself fully to a small task: chopping herbs, reading a few pages, listening to someone finish a story.'],['h2','Enough for a moment'],['p','Doing one thing at a time can feel strangely incomplete. There is always another message to check, something useful to play in the background, a way to make the interval count. But not every interval needs to be filled twice.'],['blockquote','A moment does not have to be productive to be well spent.'],['p','This is less a rule than an invitation. Choose something you already enjoy and let it be the only thing for a little while. Read slowly enough to notice the shape of a sentence. Make lunch without a screen beside the chopping board. Sit with your coffee until the cup is empty.'],['h2','Small, ordinary pleasures'],['p','The point is not to create a more impressive morning. It is to notice the morning you have. Light through a window. A warm cup in your hand. The company of a writer whose words have travelled a long way to reach you.'],['p','After twenty minutes I put the book down. There was work to do. But something about the day had changed: it had begun with an experience I could actually remember.']]}];\nlet saved=[],prefs={theme:'paper',font:'serif',size:21,width:660},current=null,tab='discover',saveFailed=false;\ntry{const s=JSON.parse(localStorage.getItem('folio-collection')||'[]');if(Array.isArray(s))saved=s.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&Array.isArray(x.body)).slice(0,100);const p=JSON.parse(localStorage.getItem('folio-preferences')||'{}');if(p&&typeof p==='object')prefs={...prefs,...p};}catch{}\nfunction persist(){try{localStorage.setItem('folio-collection',JSON.stringify(saved));return true;}catch{notify('Your browser could not save this article. Its storage may be full or disabled.');return false;}}\nfunction notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,4000)}\nfunction applyPrefs(){if(!['paper','white','dark'].includes(prefs.theme))prefs.theme='paper';if(!['serif','sans'].includes(prefs.font))prefs.font='serif';prefs.size=Math.max(16,Math.min(30,Number(prefs.size)||21));prefs.width=prefs.width===820?820:660;document.body.dataset.theme=prefs.theme;document.body.dataset.font=prefs.font;document.documentElement.style.setProperty('--article-size',prefs.size+'px');document.documentElement.style.setProperty('--article-width',prefs.width+'px');document.querySelectorAll('[data-theme]').forEach(b=>{if(b.tagName==='BUTTON')b.classList.toggle('chosen',b.dataset.theme===prefs.theme)});document.querySelectorAll('button[data-font]').forEach(b=>b.classList.toggle('chosen',b.dataset.font===prefs.font));document.querySelectorAll('button[data-width]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.width)===prefs.width));try{localStorage.setItem('folio-preferences',JSON.stringify(prefs))}catch{}}\nfunction isSaved(id){return saved.some(x=>x.id===id)}\nfunction toggleSave(article){const before=[...saved];if(isSaved(article.id))saved=saved.filter(x=>x.id!==article.id);else saved.unshift(article);if(!persist()){saved=before;return}renderCards();updateBookmark();notify(isSaved(article.id)?'A good read, saved for later.':'Removed from your collection.');}\nfunction updateBookmark(){const b=$('#bookmark');const yes=current&&isSaved(current.id);b.innerHTML=bookmarkIcon+'<span class=\"action-label\">'+(yes?'Saved':'Save')+'</span>';b.querySelector('svg').classList.toggle('saved',!!yes);b.setAttribute('aria-label',yes?'Remove from collection':'Save article');b.setAttribute('aria-pressed',String(!!yes));}\nfunction renderCards(){const list=tab==='saved'?saved:samples;$('#cards').replaceChildren();$('#empty').hidden=list.length>0;$('#section-title').textContent=tab==='saved'?'Your collection':'A few things worth reading';if(tab==='discover'){const span=document.createElement('span');span.textContent='THE FOLIO EDIT';$('#section-title').append(span)}$('#section-note').textContent=tab==='saved'?'Saved in this browser. Ready when you are.':'A small selection. A slower pace.';$('#save-count').textContent=saved.length?'('+saved.length+')':'';$('#nav-discover').classList.toggle('active',tab==='discover');$('#nav-saved').classList.toggle('active',tab==='saved');for(const article of list){const card=document.createElement('article');card.className='card';const open=document.createElement('button');open.className='card-open';open.setAttribute('aria-label','Read '+article.title);const art=document.createElement('div');art.className='art';art.innerHTML=samples.find(s=>s.id===article.id)?.art||art3;const tag=document.createElement('span');tag.className='art-tag';tag.textContent=article.category||'Your reading list';art.append(tag);const meta=document.createElement('div');meta.className='card-meta';meta.textContent=article.url?new URL(article.url).hostname.replace(/^www\\./,''):'FOLIO ORIGINAL';const dot=document.createElement('i');meta.append(dot,document.createTextNode(article.minutes+' MIN READ'));const title=document.createElement('h3');title.textContent=article.title;const desc=document.createElement('p');desc.textContent=article.excerpt;open.append(art,meta,title,desc);open.onclick=()=>openArticle(article);const bottom=document.createElement('div');bottom.className='card-bottom';const label=document.createElement('span');label.textContent=article.url?'A little time, well spent':'An original sample essay';const save=document.createElement('button');save.innerHTML=bookmarkIcon;save.querySelector('svg').classList.toggle('saved',isSaved(article.id));save.setAttribute('aria-label',isSaved(article.id)?'Remove '+article.title:'Save '+article.title);save.onclick=()=>toggleSave(article);bottom.append(label,save);card.append(open,bottom);$('#cards').append(card)}}\nfunction safeHref(value,base){try{const u=new URL(value,base);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}\nfunction renderBody(blocks,base){const root=$('#article-body');root.replaceChildren();for(const [tag,text] of blocks){if(!['p','h2','h3','blockquote','pre','ul','ol','li','img'].includes(tag)||typeof text!=='string')continue;if(tag==='img'){const href=safeHref(text,base);if(href){const img=document.createElement('img');img.src=href;img.alt='Article image';img.loading='lazy';img.referrerPolicy='no-referrer';root.append(img)}continue}const el=document.createElement(tag);el.textContent=text;root.append(el)}}\nfunction openArticle(article){current=article;$('#home').hidden=true;$('#reader').hidden=false;$('#settings').hidden=true;$('#settings-toggle').setAttribute('aria-expanded','false');$('#article-title').textContent=article.title;$('#article-source').textContent=article.url?new URL(article.url).hostname.replace(/^www\\./,''):article.category||'A moment to yourself';$('#article-dek').textContent=article.excerpt||'';$('#article-dek').hidden=!article.excerpt;$('#article-byline').textContent=[article.author||(!article.url?'Folio':''),article.minutes+' min read',article.url?'Reading view':'Original sample essay'].filter(Boolean).join(' · ');renderBody(article.body,article.url);$('#original').hidden=!article.url;if(article.url)$('#original').href=article.url;updateBookmark();document.title=article.title+' — Folio';window.scrollTo(0,0);$('#article-title').tabIndex=-1;$('#article-title').focus({preventScroll:true});}\nfunction goHome(nextTab=tab){tab=nextTab;current=null;document.body.classList.remove('focus');$('#focus-exit').hidden=true;$('#home').hidden=false;$('#reader').hidden=true;$('#progress').style.width='0';document.title='Folio — A little room to read';renderCards();window.scrollTo(0,0)}\nfunction extract(html,url){const doc=new DOMParser().parseFromString(html,'text/html');const meta=name=>doc.querySelector('meta[property=\"'+name+'\"],meta[name=\"'+name+'\"]')?.getAttribute('content')?.trim();const title=(meta('og:title')||doc.querySelector('h1')?.textContent||doc.title||'Untitled article').trim().slice(0,300);const author=(meta('author')||doc.querySelector('[rel=\"author\"]')?.textContent||'').trim().slice(0,160);const excerpt=(meta('description')||meta('og:description')||'').slice(0,400);doc.querySelectorAll('script,style,nav,header,footer,aside,form,button,input,iframe,svg,noscript,dialog,[hidden],[aria-hidden=\"true\"],[role=\"navigation\"],[role=\"dialog\"],.advertisement,.ads,.cookie-banner,.newsletter,.related-posts').forEach(x=>x.remove());const candidates=[...doc.querySelectorAll('article,main,[role=\"main\"],.post-content,.entry-content,.article-body,.story-body')];const score=node=>[...node.querySelectorAll('p')].reduce((s,p)=>s+Math.max(0,(p.textContent||'').length-(p.querySelector('a')?.textContent?.length||0)*2),0);let root=candidates.sort((a,b)=>score(b)-score(a))[0];if(!root||score(root)<250){const parentScores=new Map();doc.querySelectorAll('p').forEach(p=>{if(p.textContent.length>70){const par=p.parentElement;parentScores.set(par,(parentScores.get(par)||0)+p.textContent.length)}});root=[...parentScores.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0]||doc.body}const blocks=[];const nodes=root.querySelectorAll('h2,h3,p,blockquote,pre,li,img');for(const node of nodes){if(node.parentElement?.closest('blockquote,pre,li'))continue;if(node.tagName==='IMG'){const src=safeHref(node.getAttribute('src')||node.getAttribute('data-src'),url);if(src&&Number(node.getAttribute('width')||500)>120)blocks.push(['img',src]);continue}const text=(node.textContent||'').replace(/\\s+/g,' ').trim();if(text.length<3||text===title)continue;blocks.push([node.tagName==='LI'?'p':node.tagName.toLowerCase(),node.tagName==='LI'?'• '+text:text])}const words=blocks.filter(b=>b[0]!=='img').map(b=>b[1]).join(' ').split(/\\s+/).length;if(words<100)throw Error('There is not enough readable article text on this page. It may require a sign-in or load its content with JavaScript. Try pasting the text instead.');return{id:url,title,author,excerpt,body:blocks,minutes:Math.max(1,Math.ceil(words/230)),url,category:'From the web'}}\n$('#url-form').onsubmit=async e=>{e.preventDefault();$('#error').hidden=true;$('#read-button').disabled=true;$('#read-button').textContent='Opening…';try{const url=$('#url-input').value.trim();if(!/^https?:\\/\\//i.test(url))throw Error('Please paste a complete http or https article link.');const response=await fetch('/api/article',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url}),signal:AbortSignal.timeout(65000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to open the article.');openArticle(extract(result.html,result.url));}catch(error){$('#error').textContent=error.name==='TimeoutError'?'This article took too long to open. Please try again.':error.message;$('#error').hidden=false;}finally{$('#read-button').disabled=false;$('#read-button').innerHTML='Start reading <span>↗</span>'}};\n$('#paste-form').onsubmit=e=>{e.preventDefault();const text=$('#paste-text').value.trim();if(text.length<50)return;const article={id:'pasted-'+Date.now(),title:$('#paste-title').value.trim(),excerpt:'',author:'Pasted article',category:'Your own words',minutes:Math.max(1,Math.ceil(text.split(/\\s+/).length/230)),body:text.split(/\\n\\s*\\n/).map(t=>['p',t.trim()]).filter(t=>t[1])};$('#paste-dialog').close();openArticle(article);};\n$('#back').onclick=()=>goHome();$('#brand').onclick=()=>goHome('discover');$('#nav-discover').onclick=()=>goHome('discover');$('#nav-saved').onclick=()=>goHome('saved');$('#bookmark').onclick=()=>current&&toggleSave(current);$('#paste-open').onclick=()=>$('#paste-dialog').showModal();$('#about-open').onclick=()=>$('#about-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#settings-toggle').onclick=()=>{$('#settings').hidden=!$('#settings').hidden;$('#settings-toggle').setAttribute('aria-expanded',String(!$('#settings').hidden))};$('#size-down').onclick=()=>{prefs.size-=1;applyPrefs()};$('#size-up').onclick=()=>{prefs.size+=1;applyPrefs()};document.querySelectorAll('button[data-theme]').forEach(b=>b.onclick=()=>{prefs.theme=b.dataset.theme;applyPrefs()});document.querySelectorAll('button[data-font]').forEach(b=>b.onclick=()=>{prefs.font=b.dataset.font;applyPrefs()});document.querySelectorAll('button[data-width]').forEach(b=>b.onclick=()=>{prefs.width=Number(b.dataset.width);applyPrefs()});function exitFocus(){document.body.classList.remove('focus');$('#focus-exit').hidden=true}$('#focus').onclick=()=>{document.body.classList.add('focus');$('#focus-exit').hidden=false;$('#settings').hidden=true};$('#focus-exit').onclick=exitFocus;document.addEventListener('keydown',e=>{if(e.key==='Escape'){exitFocus();$('#settings').hidden=true;$('#settings-toggle').setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!e.target.closest('.reader-actions')){$('#settings').hidden=true;$('#settings-toggle').setAttribute('aria-expanded','false')}});window.addEventListener('scroll',()=>{if(!current)return;const max=document.documentElement.scrollHeight-window.innerHeight;$('#progress').style.width=(max>0?Math.min(100,Math.max(0,window.scrollY/max*100)):100)+'%'},{passive:true});applyPrefs();renderCards();\n</script></body></html>\n";
const fonts = {"/fonts/MartinaPlantijn-Regular.otf":"","/fonts/MartinaPlantijn-Italic.otf":"","/fonts/MartinaPlantijn-Bold.otf":"","/fonts/MartinaPlantijn-BoldItalic.otf":""};
const json = (data,status=200) => Response.json(data,{status,headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
export function validateUrl(value) {
 const url=new URL(value); const host=url.hostname.toLowerCase().replace(/\.$/,'');
 if(!['https:','http:'].includes(url.protocol)||url.username||url.password||(url.port&&!['80','443'].includes(url.port))||!host.includes('.')||host.includes(':')||host.startsWith('[')||/^\d+(\.\d+){3}$/.test(host)||/(^|\.)(localhost|local|internal|test|invalid|home|lan|arpa)$/.test(host)) throw Error('Please use a public http or https article URL.');
 return url;
}
export async function handleRequest(request, fetchPage = fetch){
 const path=new URL(request.url).pathname;
 if (request.method === 'GET' && Object.hasOwn(fonts, path)) {
   const bytes = Uint8Array.from(atob(fonts[path]), char => char.charCodeAt(0));
   return new Response(bytes, {headers: {'content-type': 'font/otf', 'cache-control': 'public, max-age=86400', 'x-content-type-options': 'nosniff'}});
 }
 if(path==='/'&&request.method==='GET') return new Response(page,{headers:{'content-type':'text/html; charset=utf-8','x-content-type-options':'nosniff','referrer-policy':'no-referrer','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src https: data:; font-src 'self'; connect-src 'self'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'self'"}});
 if(path!=='/api/article')return new Response('Not found',{status:404});
 if(request.method!=='POST')return json({error:'Method not allowed'},405);
 if(Number(request.headers.get('content-length'))>4096)return json({error:'Request too large'},413);
 try{
 const input=await request.text();if(input.length>4096)return json({error:'Request too large'},413);
 let url=validateUrl(JSON.parse(input).url);let response;
 for(let i=0;i<5;i++){
 response=await fetchPage(url,{redirect:'manual',signal:AbortSignal.timeout(12000),headers:{'User-Agent':'FolioReader/1.0 (article reading view)','Accept':'text/html,application/xhtml+xml'}});
 if(response.status>=300&&response.status<400){const location=response.headers.get('location');await response.body?.cancel();if(!location)throw Error('The article redirected without a destination.');url=validateUrl(new URL(location,url).href);continue;}break;
 }
 if(!response||!response.ok)throw Error('This website did not allow Folio to open the article. You can paste the article text instead.');
 if(!/(text\/html|application\/xhtml\+xml)/i.test(response.headers.get('content-type')||''))throw Error('This link is not a web article. Please use an article page URL.');
 const reader=response.body.getReader();let size=0;const chunks=[];
 while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>3_000_000){await reader.cancel();throw Error('This page is too large to open. Try pasting the article text.');}chunks.push(value);}
 const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
 return json({html:new TextDecoder().decode(bytes),url:url.href});
 }catch(error){return json({error:error.name==='TimeoutError'?'The website took too long to respond. Please try again.':error.message||'Unable to open this article.'},422);}
}
export default { fetch(request) { return handleRequest(request); } };
